  mariategui: {lugar:"Lima", lat:-12.05, lon:-77.04, nace:1894, muere:1930, otros:[{lugar:"Moquegua", lat:-17.19, lon:-70.94, nota:"Nació allí según la mayoría de los biógrafos (también se menciona Sayán)."},{lugar:"Roma", lat:41.9, lon:12.5, nota:"En Italia (1919–1923) se formó como marxista."}]},
  marti: {lugar:"Nueva York", lat:40.71, lon:-74.01, nace:1853, muere:1895, otros:[{lugar:"La Habana", lat:23.13, lon:-82.38, nota:"Nació allí."},{lugar:"Ciudad de México", lat:19.43, lon:-99.13, nota:"Vivió allí como periodista (1875–1876)."},{lugar:"Dos Ríos", lat:20.3, lon:-76.57, nota:"Murió allí en combate en 1895."}]},
