  rawls: {lugar:"Cambridge, Massachusetts (Harvard)", lat:42.37, lon:-71.12, nace:1921, muere:2002, otros:[{lugar:"Baltimore", lat:39.29, lon:-76.61, nota:"Nació allí."},{lugar:"Princeton", lat:40.35, lon:-74.66, nota:"Estudió y se doctoró allí."},{lugar:"Oxford", lat:51.75, lon:-1.26, nota:"Becario (1952–1953), en contacto con Hart y Berlin."}]},
